-- نبضٌ صغير — إخفاء محتوى المجتمع القديم + أسئلة شائعة من «فريق نبض» بلهجات مختلفة
-- شغّليه مرة واحدة من phpMyAdmin ← SQL. الإخفاء قابل للتراجع من صفحة الإشراف (admin.php ← إظهار).
UPDATE questions SET hidden = 1 WHERE dev <> 'nabd-team';
UPDATE answers SET hidden = 1 WHERE dev <> 'nabd-team';

SET @t = UNIX_TIMESTAMP() * 1000;

INSERT INTO questions (dev, nick, cat, title, body, t, ac) VALUES
('nabd-team','فريق نبض','t1','هو الترجيع ده هيفضل لحد امتى؟ 😩','سؤال بيوصلنا كتير من الأمهات في أول الحمل: مش قادرة آكل حاجة وبرجّع كل يوم، ده طبيعي؟', @t - 60000*1, 1),
('nabd-team','فريق نبض','food','ينفع أشرب قهوة وأنا حامل؟ ☕','سؤال متكرر: أنا متعودة على كوبايتين قهوة في اليوم، أبطلها خالص؟', @t - 60000*2, 1),
('nabd-team','فريق نبض','t2','متى أحس بحركة البيبي؟ أنا بالأسبوع 17 وما حسيت شي','من أكثر الأسئلة اللي توصلنا: هذا حملي الأول وخايفة لأني ما حسيت بأي حركة لحد الحين.', @t - 60000*3, 1),
('nabd-team','فريق نبض','sleep','كيف لازم نام؟ على ضهري ولا على جنبي؟','سؤال بيتكرر كتير: صرت بالشهر السابع وما عم بعرف نام مرتاحة، شو أحسن وضعية؟', @t - 60000*4, 1),
('nabd-team','فريق نبض','food','واش نقدر ناكل الحوت والتونة فالحمل؟ 🐟','سؤال كيوصلنا بزاف: كنحب الحوت والسردين، واش ما فيه حتى مشكل للجنين؟', @t - 60000*5, 1),
('nabd-team','فريق نبض','t3','الطلق الكاذب والحقيقي.. كيف أفرق بينهم؟','سؤال يتكرر وايد بالشهر التاسع: بطني يشد علي كل شوي، أروح المستشفى ولا أنطر؟', @t - 60000*6, 1),
('nabd-team','فريق نبض','other','هل يجوز أصوم رمضان وأنا حامل؟ 🌙','سؤال يصلنا كل سنة قبل رمضان: أنا في الشهر الخامس وصحتي زينة، أصوم ولا لا؟', @t - 60000*7, 1),
('nabd-team','فريق نبض','t2','الحموضة تاعباني جداً خصوصاً بالليل 🔥','سؤال بيتكرر: ببقى مش عارفة أنام من الحرقان في صدري، أعمل إيه؟', @t - 60000*8, 1),
('nabd-team','فريق نبض','mental','دايماً قلقانة على البيبي ومش عارفة أرتاح 🤍','رسالة بتوصلنا كتير: بفضل أدور على النت على كل عرض وبخاف من أي حاجة.', @t - 60000*9, 1),
('nabd-team','فريق نبض','bf','كيف أعرف إن حليبي يكفي البيبي؟','سؤال يتكرر وايد بعد الولادة: البيبي يرضع كل شوي وأحس إنه ما يشبع.', @t - 60000*10, 1),
('nabd-team','فريق نبض','t1','شو الأدوية المسموحة للصداع بالحمل؟ 💊','سؤال كتير بيوصلنا: راسي عم يوجعني كل يوم، فيني آخد مسكّن؟', @t - 60000*11, 1),
('nabd-team','فريق نبض','t3','إيه اللي لازم يكون في شنطة الولادة؟ 👜','سؤال بيتكرر كتير في الشهر الأخير: عايزة أجهز الشنطة ومش عارفة أبدأ منين.', @t - 60000*12, 1);

-- رد فريق نبض على كل سؤال (بنفس اللهجة)
INSERT INTO answers (qid, dev, nick, ai, body, t)
SELECT id, 'nabd-team', 'فريق نبض', 0, CASE title
  WHEN 'هو الترجيع ده هيفضل لحد امتى؟ 😩' THEN 'الترجيع في أول الحمل شائع جداً، وغالباً بيتحسن بعد الأسبوع 12 إلى 14 بإذن الله 🌸\n• كُلي وجبات صغيرة كل ساعتين، وبسكوت ناشف قبل ما تقومي من السرير.\n• الزنجبيل والليمون بيساعدوا، وابعدي عن الأكل الدسم والروايح.\n• اشربي مية على رشفات بين الوجبات.\nلو مش قادرة تحتفظي بأي أكل أو شرب طول اليوم، أو البول قلّ، أو وزنك بينزل، كلمي دكتورك على طول.'
  WHEN 'ينفع أشرب قهوة وأنا حامل؟ ☕' THEN 'مش لازم تبطليها خالص 😊 المهم الكافيين ما يزيدش عن 200 ملغ في اليوم، يعني تقريباً كوباية أو اتنين صغيرين.\nخدي بالك إن الشاي والكولا والشوكولاتة فيهم كافيين برضه. وابعدي تماماً عن مشروبات الطاقة.'
  WHEN 'متى أحس بحركة البيبي؟ أنا بالأسبوع 17 وما حسيت شي' THEN 'لا تخافين حبيبتي 🤍 في الحمل الأول الحركة تبين غالباً بين الأسبوع 18 و22، وأول شي تحسينها مثل رفرفة خفيفة أو فقاعات.\nمن الأسبوع 28 تابعي نمط حركته كل يوم، وإذا حسيتي إنها قلت فروحي للمستشفى نفس اليوم.'
  WHEN 'كيف لازم نام؟ على ضهري ولا على جنبي؟' THEN 'الأحسن تنامي على جنبك، اليمين أو الشمال، التنين آمنين 💤 خصوصاً بعد الأسبوع 28.\nحطي مخدة بين ركبك ومخدة تحت بطنك، وإذا فقتي على ضهرك ما تقلقي، بس ارجعي على جنبك.'
  WHEN 'واش نقدر ناكل الحوت والتونة فالحمل؟ 🐟' THEN 'إيه، الحوت مزيان بزاف لمخ الجنين 🐟 مرتين فالسيمانة من الأنواع اللي فيها زئبق قليل بحال السردين والسلمون والقمرون المطبوخ.\nالتونة المعلبة ماشي مشكل بالاعتدال. تجنبي الحوت النيء بحال السوشي، والحوت الكبير بحال القرش وأبو سيف.'
  WHEN 'الطلق الكاذب والحقيقي.. كيف أفرق بينهم؟' THEN 'الطلق الكاذب ما يكون منتظم، وما يزيد قوة، ويخف إذا ارتحتي أو شربتي ماي.\nأما الحقيقي فيكون منتظم، ويقرب ويقوى شوي شوي.\nروحي المستشفى إذا صار الطلق كل 5 دقايق لمدة ساعة، أو نزل ماي أو دم، أو قلت حركة البيبي. وإذا كنتي قبل الأسبوع 37 وصار عندك طلق منتظم، روحي فوراً.'
  WHEN 'هل يجوز أصوم رمضان وأنا حامل؟ 🌙' THEN 'الحامل مرخّص لها بالإفطار إذا خافت على نفسها أو على الجنين 🌙\nوطبياً القرار يعتمد على حالتك، فلازم تستشيرين طبيبتك قبل رمضان، خصوصاً إذا عندك سكري أو فقر دم.\nوإذا صمتي، أفطري على طول إذا حسيتي بدوخة شديدة، أو قلت حركة البيبي، أو قل البول.'
  WHEN 'الحموضة تاعباني جداً خصوصاً بالليل 🔥' THEN 'الحموضة من أكتر حاجات الحمل المزعجة، بس ليها حلول 🔥\n• كلي وجبات صغيرة، وما تناميش قبل ساعتين من الأكل.\n• ارفعي راس السرير شوية.\n• قللي الحراق والدسم والمياه الغازية.\nفيه أدوية حموضة آمنة في الحمل، اسألي الدكتور أو الصيدلي عن المناسب ليكي.'
  WHEN 'دايماً قلقانة على البيبي ومش عارفة أرتاح 🤍' THEN 'إحساسك مفهوم جداً وكتير من الأمهات بيمروا بيه 🤍\n• حاولي تقللي البحث على النت، واسألي دكتورك مباشرة عن أي حاجة مقلقاكي.\n• اتمشي، واتكلمي مع حد بتثقي فيه.\nلو القلق أو الحزن استمر أكتر من أسبوعين، أو أثّر على نومك وأكلك، كلمي دكتورك، فده شائع وليه علاج. وإنتي مش لوحدك 💗'
  WHEN 'كيف أعرف إن حليبي يكفي البيبي؟' THEN 'إن شاء الله يكفي 🤱 علامات إن البيبي شبعان:\n• 6 حفاضات مبللة أو أكثر يومياً بعد اليوم الخامس.\n• وزنه يزيد بعد أول أسبوعين.\n• يكون هادي بعد الرضعة.\nالرضاعة الكثيرة طبيعية، 8 إلى 12 مرة باليوم، وهي اللي تزيد الحليب. وإذا قلت الحفاضات أو صار نعسان وايد، راجعي دكتور الأطفال.'
  WHEN 'شو الأدوية المسموحة للصداع بالحمل؟ 💊' THEN 'الباراسيتامول (بنادول) هو المسكّن المفضّل بالحمل، بأقل جرعة ولأقصر مدة 💊\nابعدي عن البروفين والفولتارين، خصوصاً بعد الأسبوع 20، إلا إذا الدكتور وصفهن.\nاشربي مي منيح ونامي كفاية. وإذا كان الصداع قوي وما عم يروح، أو معه زغللة أو ورم، روحي ع الدكتور اليوم.'
  WHEN 'إيه اللي لازم يكون في شنطة الولادة؟ 👜' THEN 'جهزيها من الأسبوع 34 تقريباً 👜\nليكي: البطاقة والملف الطبي، وهدوم مريحة، وفوط نفاس، وبرا رضاعة، وشاحن، وسناكس.\nللبيبي: هدوم قطن، وحفاضات مقاس نيوبورن، وبطانية، وكرسي العربية.\nوفيه قائمة جاهزة في التطبيق في قسم «المزيد» ✅'
END, @t - 30000
FROM questions WHERE dev = 'nabd-team' AND id NOT IN (SELECT qid FROM (SELECT qid FROM answers WHERE dev = 'nabd-team') x);
